CREATE TABLE IF NOT EXISTS service_tickets(id TEXT PRIMARY KEY,customer_id TEXT NOT NULL REFERENCES customers(id),title TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',priority TEXT NOT NULL DEFAULT 'medium' CHECK(priority IN ('low','medium','high','critical')),status TEXT NOT NULL DEFAULT 'open' CHECK(status IN ('open','in_progress','on_hold','resolved','closed')),assigned_to TEXT REFERENCES users(id),created_by TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,first_response_at TEXT,resolved_at TEXT,response_due_at TEXT,resolution_due_at TEXT);CREATE INDEX IF NOT EXISTS idx_service_tickets_customer ON service_tickets(customer_id,status);CREATE TABLE IF NOT EXISTS ticket_events(id TEXT PRIMARY KEY,ticket_id TEXT NOT NULL REFERENCES service_tickets(id),actor_id TEXT REFERENCES users(id),event_type TEXT NOT NULL,note TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);